// DeleteSurroundingText delete text.
//
// Remove the surrounding text.
//
// This request will be handled on the text_input side directly following
// a commit_string request.
func (o *InputMethodContextV1) DeleteSurroundingText(index int32, length uint32) error {
	return o.proxy.SendRequest(InputMethodContextV1RequestDeleteSurroundingText, &InputMethodContextV1DeleteSurroundingTextRequest{
		Index:  index,
		Length: length,
	})
}

// CursorPosition set cursor to a new position.
//
// Set the cursor and anchor to a new position. Index is the new cursor
// position in bytes (when >= 0 this is relative to the end of the inserted text,
// otherwise it is relative to the beginning of the inserted text). Anchor is
// the new anchor position in bytes (when >= 0 this is relative to the end of the
// inserted text, otherwise it is relative to the beginning of the inserted
// text). When there should be no selected text, anchor should be the same
// as index.
//
// This request will be handled on the text_input side directly following
// a commit_string request.
func (o *InputMethodContextV1) CursorPosition(index int32, anchor int32) error {
	return o.proxy.SendRequest(InputMethodContextV1RequestCursorPosition, &InputMethodContextV1CursorPositionRequest{
		Index:  index,
		Anchor: anchor,
	})
}

func (o *InputMethodContextV1) ModifiersMap(map_ []byte) error {
	return o.proxy.SendRequest(InputMethodContextV1RequestModifiersMap, &InputMethodContextV1ModifiersMapRequest{
		Map: map_,
	})
}

// Keysym keysym.
//
// Notify when a key event was sent. Key events should not be used for
// normal text input operations, which should be done with commit_string,
// delete_surrounding_text, etc. The key event follows the wl_keyboard key
// event convention. Sym is an XKB keysym, state is a wl_keyboard key_state.
func (o *InputMethodContextV1) Keysym(serial uint32, time uint32, sym uint32, state uint32, modifiers uint32) error {
	return o.proxy.SendRequest(InputMethodContextV1RequestKeysym, &InputMethodContextV1KeysymRequest{
		Serial:    serial,
		Time:      time,
		Sym:       sym,
		State:     state,
		Modifiers: modifiers,
	})
}

// GrabKeyboard grab hardware keyboard.
//
// Allow an input method to receive hardware keyboard input and process
// key events to generate text events (with pre-edit) over the wire. This
// allows input methods which compose multiple key events for inputting
// text like it is done for CJK languages.
func (o *InputMethodContextV1) GrabKeyboard() (*wayland.Proxy, error) {
	conn := o.proxy.Conn()
	p := wayland.NewProxy(conn)
	p.SetVersion(o.proxy.Version())

	conn.RegisterProxy(p)
	err := conn.SendRequest(o.proxy.ID(), InputMethodContextV1RequestGrabKeyboard, &InputMethodContextV1GrabKeyboardRequest{
		Keyboard: wire.NewID(p.ID()),
	})
	if err != nil {
		conn.UnregisterProxy(p.ID())
		return nil, err
	}
	return p, nil
}

// Key forward key event.
//
// Forward a wl_keyboard::key event to the client that was not processed
// by the input method itself. Should be used when filtering key events
// with grab_keyboard.  The arguments should be the ones from the
// wl_keyboard::key event.
//
// For generating custom key events use the keysym request instead.
func (o *InputMethodContextV1) Key(serial uint32, time uint32, key uint32, state uint32) error {
	return o.proxy.SendRequest(InputMethodContextV1RequestKey, &InputMethodContextV1KeyRequest{
		Serial: serial,
		Time:   time,
		Key:    key,
		State:  state,
	})
}

// Modifiers forward modifiers event.
//
// Forward a wl_keyboard::modifiers event to the client that was not
// processed by the input method itself.  Should be used when filtering
// key events with grab_keyboard. The arguments should be the ones
// from the wl_keyboard::modifiers event.
func (o *InputMethodContextV1) Modifiers(serial uint32, modsDepressed uint32, modsLatched uint32, modsLocked uint32, group uint32) error {
	return o.proxy.SendRequest(InputMethodContextV1RequestModifiers, &InputMethodContextV1ModifiersRequest{
		Serial:        serial,
		ModsDepressed: modsDepressed,
		ModsLatched:   modsLatched,
		ModsLocked:    modsLocked,
		Group:         group,
	})
}

func (o *InputMethodContextV1) Language(serial uint32, language string) error {
	return o.proxy.SendRequest(InputMethodContextV1RequestLanguage, &InputMethodContextV1LanguageRequest{
		Serial:   serial,
		Language: language,
	})
}

func (o *InputMethodContextV1) TextDirection(serial uint32, direction uint32) error {
	return o.proxy.SendRequest(InputMethodContextV1RequestTextDirection, &InputMethodContextV1TextDirectionRequest{
		Serial:    serial,
		Direction: direction,
	})
}

// BindInputMethodContextV1 binds the zwp_input_method_context_v1 global advertised by the server.
// version is the version requested by the application; it must be within
// [1, VersionInputMethodContextV1] or ErrVersionMismatch is returned. Servers newer
// than this library may advertise a higher version: clamp the advertised
// version with the builtin min, e.g. BindInputMethodContextV1(reg, name, min(g.Version,
// VersionInputMethodContextV1)), to bind at the highest mutually supported version.
func BindInputMethodContextV1(b wayland.Binder, name uint32, version uint32) (*InputMethodContextV1, error) {
	if version < 1 || version > VersionInputMethodContextV1 {
		return nil, wayland.ErrVersionMismatch
	}
	p, err := b.Bind(name, InterfaceInputMethodContextV1, version)
	if err != nil {
		return nil, err
	}
	x := NewInputMethodContextV1(p)
	x.proxy.SetVersion(version)
	return x, nil
}
